// writeAll writes the given lines to the ring, one Write per line, and fails
// the test on the first short write or error (the copier-failure posture).
func writeAll(t *testing.T, r *logRing, lines ...string) {
	t.Helper()
	for _, l := range lines {
		n, err := r.Write([]byte(l + "\n"))
		if err != nil {
			t.Fatalf("write %q: %v", l, err)
		}
		if n != len(l)+1 {
			t.Fatalf("write %q: short write %d/%d", l, n, len(l)+1)
		}
	}
}

// wantLines is the shared assertion: the tail reads oldest-first, exactly want.
func wantLines(t *testing.T, got, want []string) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("tail = %d lines %v, want %d", len(got), got, len(want))
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("tail[%d] = %q, want %q (oldest-first order)", i, got[i], want[i])
		}
	}
}

// TestLogRing is the plugin-admin-surfaces log-capture unit test (scenario
// f38838b4b9336498): the ring keeps the tail, clamps long lines, reassembles
// arbitrarily-chunked writes into lines, and reads out a detached copy.
func TestLogRing(t *testing.T) {
	t.Run("tail_wins_oldest_drop_first", func(t *testing.T) {
		r := &logRing{}
		for i := 0; i < logRingLines+44; i++ {
			writeAll(t, r, fmt.Sprintf("l%d", i))
		}
		got := r.lines()
		if len(got) != logRingLines {
			t.Fatalf("tail = %d lines, want %d", len(got), logRingLines)
		}
		want := make([]string, logRingLines)
		for i := range want {
			want[i] = fmt.Sprintf("l%d", i+44)
		}
		wantLines(t, got, want)
	})

	t.Run("overlong_line_is_clamped", func(t *testing.T) {
		r := &logRing{}
		writeAll(t, r, "before")
		over := strings.Repeat("x", logLineMaxBytes+100)
		writeAll(t, r, over)
		writeAll(t, r, "after")
		got := r.lines()
		wantLines(t, got, []string{"before", strings.Repeat("x", logLineMaxBytes), "after"})
	})

	t.Run("chunks_reassemble_into_lines", func(t *testing.T) {
		r := &logRing{}
		// go-plugin's copier writes in arbitrary chunks — feed the same bytes
		// one byte at a time plus a split mid-line across two writes.
		for _, b := range []byte("alpha\nbeta\ngamma\ndel") {
			if _, err := r.Write([]byte{b}); err != nil {
				t.Fatalf("write byte: %v", err)
			}
		}
		if _, err := r.Write([]byte("ta\n")); err != nil {
			t.Fatalf("write tail: %v", err)
		}
		wantLines(t, r.lines(), []string{"alpha", "beta", "gamma", "delta"})
	})

	t.Run("read_returns_a_detached_copy", func(t *testing.T) {
		r := &logRing{}
		writeAll(t, r, "kept")
		got := r.lines()
		got[0] = "mutated"
		wantLines(t, r.lines(), []string{"kept"})
	})

	t.Run("concurrent_writes_and_reads", func(t *testing.T) {
		r := &logRing{}
		var wg sync.WaitGroup
		for w := 0; w < 4; w++ {
			wg.Add(1)
			go func(w int) {
				defer wg.Done()
				for i := 0; i < 100; i++ {
					if _, err := r.Write([]byte(fmt.Sprintf("w%d-l%d\n", w, i))); err != nil {
						t.Errorf("write: %v", err)
					}
					_ = r.lines()
				}
			}(w)
		}
		wg.Wait()
		if got := len(r.lines()); got != logRingLines {
			t.Fatalf("tail = %d lines, want %d (every line captured exactly once)", got, logRingLines)
		}
	})
}
